mapper.select:
SELECT p.share_id, p.resource_instance_key, p.target_type, p.target_id,
    p.start_time, p.expire_time, p.projection_epoch, NULL AS team_id,
    p.scope_type, p.folder_path, p.collection_resource_ids_json
FROM iam_share_acl_projection p
WHERE p.tenant_id = #{tenantId} AND p.resource_id = #{resourceId}
  AND (
      p.resource_instance_key = #{resourceInstanceKey}
      OR p.scope_type IN ('FOLDER_INHERITED', 'COLLECTION')
  )
  AND p.operation_id = #{operationId} AND p.status = 'ACTIVE'
  AND p.start_time <= #{evaluatedAt} AND p.expire_time > #{evaluatedAt}
  AND (
      (p.target_type = 'USER' AND p.target_id = #{subjectUserId})

          OR (p.target_type = 'TEAM' AND p.target_id IN
          #{id})

      OR (p.target_type = 'ROLE' AND EXISTS (
          SELECT 1 FROM iam_user_role ur
          WHERE ur.tenant_id = #{tenantId}
            AND ur.user_id = #{subjectUserId}
            AND ur.role_id = p.target_id
            AND ur.status = 'ACTIVE'
            AND ur.active_slot = 1
            AND ur.start_time <= #{evaluatedAt}
            AND (ur.expire_time IS NULL OR ur.expire_time > #{evaluatedAt})
      ))
  )

UNION ALL
SELECT p.share_id, p.resource_instance_key, p.target_type, p.target_id,
    p.start_time, p.expire_time, p.projection_epoch, tmr.team_id,
    p.scope_type, p.folder_path, p.collection_resource_ids_json
FROM iam_share_acl_projection p
JOIN iam_team_member_role tmr
  ON tmr.tenant_id = p.tenant_id
 AND tmr.team_role_id = p.target_id
 AND tmr.user_id = #{subjectUserId}
 AND tmr.team_id IN
 #{id}
 AND tmr.status = 'ACTIVE'
 AND tmr.active_slot = 1
 AND tmr.start_time <= #{evaluatedAt}
 AND (tmr.expire_time IS NULL OR tmr.expire_time > #{evaluatedAt})
WHERE p.tenant_id = #{tenantId} AND p.resource_id = #{resourceId}
  AND (
      p.resource_instance_key = #{resourceInstanceKey}
      OR p.scope_type IN ('FOLDER_INHERITED', 'COLLECTION')
  )
  AND p.operation_id = #{operationId} AND p.status = 'ACTIVE'
  AND p.start_time <= #{evaluatedAt} AND p.expire_time > #{evaluatedAt}
  AND p.target_type = 'TEAM_ROLE'

ORDER BY share_id

SELECT expected_epoch, applied_epoch
FROM iam_share_security_epoch
WHERE tenant_id = #{tenantId} AND resource_id = #{resourceId}

mapper.update:
UPDATE iam_share_acl_projection
SET status = 'REVOKED', projection_epoch = #{epoch},
    version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND share_id = #{shareId}
  AND target_type = #{targetType} AND target_id = #{targetId}
  AND operation_id IN
  #{id}
  AND projection_epoch < #{epoch}

mapper.delete:
DELETE FROM iam_share_field_grant_projection
WHERE tenant_id = #{tenantId} AND share_id = #{shareId}
  AND projection_epoch < #{epoch}
